private void validateClient() {
    Objects.requireNonNull(endpoint, "'endpoint' cannot be null.");
    if (hub == null || hub.isEmpty()) {
        throw LOGGER.logExceptionAsError(
            new IllegalStateException("hub is not valid - it must be non-null and non-empty."));
    }
}

private HttpPipeline createHttpPipeline() {
    Configuration buildConfiguration
        = (configuration == null) ? Configuration.getGlobalConfiguration() : configuration;
    HttpLogOptions localHttpLogOptions = this.httpLogOptions == null ? new HttpLogOptions() : this.httpLogOptions;
    ClientOptions localClientOptions = this.clientOptions == null ? new ClientOptions() : this.clientOptions;
    List<HttpPipelinePolicy> policies = new ArrayList<>();
    String clientName = PROPERTIES.getOrDefault(SDK_NAME, "UnknownName");
    String clientVersion = PROPERTIES.getOrDefault(SDK_VERSION, "UnknownVersion");
    String applicationId = CoreUtils.getApplicationId(localClientOptions, localHttpLogOptions);
    policies.add(new UserAgentPolicy(applicationId, clientName, clientVersion, buildConfiguration));
    policies.add(new RequestIdPolicy());
    policies.add(new AddHeadersFromContextPolicy());
    HttpHeaders headers = CoreUtils.createHttpHeadersFromClientOptions(localClientOptions);
    if (headers != null) {
        policies.add(new AddHeadersPolicy(headers));
    }
    this.pipelinePolicies.stream()
        .filter(p -> p.getPipelinePosition() == HttpPipelinePosition.PER_CALL)
        .forEach(policies::add);
    HttpPolicyProviders.addBeforeRetryPolicies(policies);
    policies.add(ClientBuilderUtil.validateAndGetRetryPolicy(retryPolicy, retryOptions, new RetryPolicy()));
    policies.add(new AddDatePolicy());
    if (keyCredential != null) {
        policies.add(new WebPubSubAuthenticationPolicy(keyCredential));
    } else if (tokenCredential != null) {
        policies.add(new BearerTokenAuthenticationPolicy(tokenCredential, DEFAULT_SCOPES));
    } else {
        throw LOGGER
            .logExceptionAsError(new IllegalStateException("No credential available to create the client."));
    }
    if (!CoreUtils.isNullOrEmpty(reverseProxyEndpoint)) {
        policies.add(new ReverseProxyPolicy(reverseProxyEndpoint));
    }
    this.pipelinePolicies.stream()
        .filter(p -> p.getPipelinePosition() == HttpPipelinePosition.PER_RETRY)
        .forEach(policies::add);
    HttpPolicyProviders.addAfterRetryPolicies(policies);
    policies.add(new HttpLoggingPolicy(localHttpLogOptions));
    return new HttpPipelineBuilder().policies(policies.toArray(new HttpPipelinePolicy[0]))
        .httpClient(httpClient)
        .clientOptions(localClientOptions)
        .build();
}

